// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: _baseToken and _nft and other init args. We need at least one param — choose address baseToken and uint16 feeRate and uint128 vBase and vNft to give variety.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep inputs wide but make feeRate within allowed range to avoid revert from FeeRateTooHigh.
        uint16 feeRate = _feeRate % 5001; // 0..5000 allowed

        // Ensure nft is non-zero (initialize doesn't require but many downstream calls might; keep admissible)
        if (_nft == address(0)) {
            _nft = address(1);
        }

        // Call initialize and capture whether it succeeds.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // Only proceed to check the invariant if initialize returned successfully.
        if (!ok) return; // if initialization reverted, property vacuously holds for that input

        // General rule: after initialize, c.baseToken() == the _baseToken argument passed in.
        // The buggy mutant sets baseToken = address(0) unconditionally, so when _baseToken != address(0) the mutant will violate this.
        assertTrue(c.baseToken() == _baseToken);
    }
}

