pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: an address candidate for _baseToken and arbitrary other params
    function testFuzz_property(address fuzzBaseToken, address fuzzNft, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        // keep wide domain but avoid zeroing invariants that might be invalid inputs
        // feeRate must be within allowed range for successful initialize on reference
        vm.assume(feeRate <= 60000); // generous upper bound, reference guards >5000 only

        // Call initialize as an arbitrary caller (fuzzer supplies fuzzBaseToken but caller is this test contract)
        // We need to observe that reference sets baseToken == fuzzBaseToken after initialize
        bool ok;
        try c.initialize(fuzzBaseToken, fuzzNft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted, nothing to assert about state; the universal property only applies when initialize succeeds.
        if (!ok) return;

        // Single assertion: reference should have stored the provided _baseToken as baseToken
        // The mutant that sets baseToken = msg.sender will make this fail when msg.sender != fuzzBaseToken.
        assertTrue(c.baseToken() == fuzzBaseToken);
    }
}

