pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the parameters to find cases where _baseToken == address(0) must be accepted by reference but rejected by mutant
    function testFuzz_property(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {
        // Keep feeRate within admissible bound to avoid unrelated revert
        // but allow the fuzzer to choose wide values; constrain only to admissible range
        if (feeRate > 5000) feeRate = 5000;

        bool ok;
        // call initialize and capture whether it succeeded (reference should accept baseToken==address(0))
        try c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference C accepts initialization even when baseToken == address(0).
        // Therefore, for all inputs, ok must be true. The mutant inserts `require(_baseToken != address(0))` and
        // will make ok == false for some inputs (those with baseToken == address(0)).
        assertTrue(ok);
    }
}

